+  if (ship->dock > 0)
+  {
+    send_to_char(ch, "%s is berthed; order 'undock' to cast off first.\r\n", ship->name);
+    return TRUE;
+  }
+  if (ship->anchored)
+  {
+    send_to_char(ch, "%s rides at anchor; order 'undock' to weigh anchor first.\r\n", ship->name);
+    return TRUE;
+  }
+  return FALSE;
+}
