+    {
+      new_type = ROOM_TYPE_CARGO;
+    }
+    else
+    {
+      /* Random selection from common room types */
+      switch (rand_number(1, 5))
+      {
+      case 1:
+        new_type = ROOM_TYPE_QUARTERS;
