+    return;
+  }
+  if (mysql_query(connection, "CREATE TEMPORARY TABLE trade_commodities ("
+                              "commodity_id INT AUTO_INCREMENT PRIMARY KEY, "
+                              "name VARCHAR(63) NOT NULL UNIQUE, "
+                              "base_price INT NOT NULL DEFAULT 10, "
